// Reorder.jsx — Firestore version
// ============================================================
// Keyed by ProductCode + LocationID. One Reorder Level /
// Reorder Qty per row that writes to BOTH:
//   - ProductStock  (location-specific — source of truth)
//   - Products      (product-level default)
//
// Firestore collections used:
//   - Products      (product master)
//   - ProductStock  (per-location stock + reorder settings)
//   - Locations     (via COLLECTIONS.LOCATIONS)
// ============================================================

import React, {
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
} from "react";

import {
  doc,
  writeBatch,
  serverTimestamp,
} from "firebase/firestore";

import { PermissionsContext } from "../context/PermissionsContext.jsx";

import { db } from "../firebase.js";
import { COLLECTIONS, listCollection } from "../lib/firestore.js";
import { AuthContext } from "../pos/SERVER/AuthContext.js";

/* ======================================================
   COLLECTIONS
====================================================== */

const PRODUCTS = COLLECTIONS?.PRODUCTS ?? "Products";
const PRODUCT_STOCK = COLLECTIONS?.PRODUCT_STOCK ?? "ProductStock";

/* ======================================================
   CONSTANTS
====================================================== */

const REORDER_MODULE = "Reorder";

const ACTION_TO_COLUMN = {
  View: "CanView",
  Add: "CanAdd",
  Edit: "CanEdit",
  Delete: "CanDelete",
  Print: "CanPrint",
};

const FIELD_TO_COLUMN = {
  CostPrice: "CanViewCostPrice",
  SellingPrice: "CanViewSellingPrice",
  Profit: "CanViewProfit",
};

/* ======================================================
   HELPERS
====================================================== */

const pick = (obj, ...keys) => {
  for (const key of keys) {
    if (obj && obj[key] !== undefined && obj[key] !== null) {
      return obj[key];
    }
  }
  return "";
};

const toNumber = (value) => {
  const n = Number(value);
  return Number.isFinite(n) ? n : 0;
};

// Return the first candidate that parses to a finite number (0 is
// valid). Returns null when nothing usable is present so callers
// can distinguish "0" from "no value".
const firstNumeric = (candidates) => {
  for (const candidate of candidates) {
    if (candidate === null || candidate === undefined) continue;
    if (
      typeof candidate === "string" &&
      candidate.trim() === ""
    ) {
      continue;
    }
    const n = Number(candidate);
    if (Number.isFinite(n)) return n;
  }
  return null;
};

const formatNumber = (value) =>
  Number(value || 0).toLocaleString("en-US", {
    maximumFractionDigits: 3,
  });

const isBlank = (value) =>
  value === "" || value === null || value === undefined;

// A row's identity is its ProductStock doc id (falls back to
// ProductCode+LocationID if the id is somehow missing).
const rowKeyOf = (item) =>
  item._stockDocId ||
  `${item.ProductCode ?? "?"}-${item.LocationID ?? "n"}`;

/* ======================================================
   PERMISSION HOOK  (wraps the shared context)
   ------------------------------------------------------
   Rules of hooks:
     • ALL hooks run unconditionally, same order every render.
     • Branching / fallbacks happen AFTER all hooks are called.
   We use useContext(PermissionsContext) directly (rather than
   the usePermissionsContext helper) because useContext never
   throws when the provider is missing — it just returns null.
   That lets us keep a safe "grant access when provider is not
   mounted" fallback without a try/catch around a hook.
====================================================== */

function usePermissions() {
  const ctx = useContext(PermissionsContext);

  const can = useCallback(
    (moduleName, action = "View") => {
      if (!ctx) return true;
      const column = ACTION_TO_COLUMN[action] || action;
      return ctx.can(moduleName, null, column);
    },
    [ctx]
  );

  const canField = useCallback(
    (moduleName, field) => {
      if (!ctx) return true;
      const column = FIELD_TO_COLUMN[field];
      if (!column) return true;
      return ctx.can(moduleName, null, column);
    },
    [ctx]
  );

  // All hooks have run — safe to branch now.
  if (!ctx) {
    return {
      permissions: {},
      loading: false,
      error: null,
      reload: () => {},
      can,
      canField,
    };
  }

  return {
    permissions: ctx.permissions,
    loading: ctx.loading,
    error: ctx.error,
    reload: ctx.reload,
    can,
    canField,
  };
}

/* ======================================================
   COMPONENT
====================================================== */

function Reorder() {
  const { user } = useContext(AuthContext);
  const username = user?.username || "admin";

  const [products, setProducts] = useState([]);
  const [search, setSearch] = useState("");
  const [loading, setLoading] = useState(true);
  const [savingId, setSavingId] = useState(null);
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");

  const { can, loading: permsLoading } = usePermissions();
  const canViewReorder = can(REORDER_MODULE, "View");
  const canEditReorder = can(REORDER_MODULE, "Edit");
  const canPrintReorder = can(REORDER_MODULE, "Print");

  /* ======================================================
     LOAD PRODUCTS + STOCK + LOCATIONS
  ====================================================== */

  const loadProducts = useCallback(async () => {
    try {
      setLoading(true);
      setError("");
      setMessage("");

      const [stockRows, productRows, locationRows] =
        await Promise.all([
          listCollection(PRODUCT_STOCK, {
            where: [["IsDelete", "==", 0]],
          }),
          listCollection(PRODUCTS, {
            where: [["IsDelete", "==", 0]],
          }),
          listCollection(COLLECTIONS.LOCATIONS, {
            where: [["IsDelete", "==", 0]],
          }),
        ]);

      /* ---- Product + location lookup maps ---- */

      const productMap = {};
      productRows.forEach((p) => {
        const code = String(
          pick(p, "ProductCode", "productcode") || ""
        ).trim();
        if (code) productMap[code] = p;
      });

      const locationMap = {};
      locationRows.forEach((l) => {
        const id = String(
          pick(
            l,
            "LocationID",
            "locationID",
            "locationid",
            "id"
          ) || ""
        );
        if (id) locationMap[id] = l;
      });

      /* ---- Join stock rows with product + location ---- */

      const joinedRows = stockRows
        .map((stock) => {
          const code = String(
            pick(stock, "ProductCode", "productcode") || ""
          ).trim();

          const product = productMap[code] || {};

          const locId = String(
            pick(
              stock,
              "LocationID",
              "locationID",
              "locationid"
            ) || ""
          );

          const location = locationMap[locId] || {};

          return {
            _stockDocId: stock.id,
            _productDocId: product.id || "",

            ProductCode: code,

            ProductName:
              pick(product, "ProductName", "productname") ||
              pick(stock, "ProductName", "productname") ||
              "",

            LocationID: locId,

            LocationName:
              pick(location, "LocationName", "locationname") ||
              pick(stock, "LocationName", "locationname") ||
              "",

            Stock: toNumber(
              pick(
                stock,
                "Stock",
                "stock",
                "CurrentStock",
                "currentStock"
              )
            ),

            ReOrderLevel:
              firstNumeric([
                stock.ReOrderLevel,
                stock.ProductReOrderLevel,
                stock.StockReOrderLevel,
              ]) ?? 0,

            ReOrderQty:
              firstNumeric([
                stock.ReOrderQty,
                stock.ProductReOrderQty,
                stock.StockReOrderQty,
                stock.ReOrderQuantity,
              ]) ?? 0,
          };
        })
        .filter((row) => row.ProductCode);

      setProducts(joinedRows);
    } catch (err) {
      console.error("LOAD REORDER PRODUCTS ERROR:", err);
      setError(
        err.message || "Unable to load reorder settings."
      );
    } finally {
      setLoading(false);
    }
  }, []);

  /* ======================================================
     INITIAL LOAD / PERMISSION GUARD
  ====================================================== */

  useEffect(() => {
    if (permsLoading) return;

    if (!canViewReorder) {
      setLoading(false);
      setProducts([]);
      return;
    }

    loadProducts();
  }, [permsLoading, canViewReorder, loadProducts]);

  /* ======================================================
     AUTO-CLEAR MESSAGES
  ====================================================== */

  useEffect(() => {
    if (!message && !error) return undefined;

    const timer = setTimeout(() => {
      setMessage("");
      setError("");
    }, 4000);

    return () => clearTimeout(timer);
  }, [message, error]);

  /* ======================================================
     SEARCH FILTER
  ====================================================== */

  const filteredProducts = useMemo(() => {
    const q = search.trim().toLowerCase();
    if (!q) return products;

    return products.filter((item) => {
      const code = String(item.ProductCode || "").toLowerCase();
      const name = String(item.ProductName || "").toLowerCase();
      const locName = String(item.LocationName || "").toLowerCase();
      const locId = String(item.LocationID || "").toLowerCase();

      return (
        code.includes(q) ||
        name.includes(q) ||
        locName.includes(q) ||
        locId.includes(q)
      );
    });
  }, [products, search]);

  /* ======================================================
     FIELD CHANGE  (local state only)
  ====================================================== */

  const handleFieldChange = (targetKey, field, value) => {
    if (!canEditReorder) return;

    setProducts((current) =>
      current.map((row) =>
        rowKeyOf(row) === targetKey
          ? { ...row, [field]: value }
          : row
      )
    );
  };

  /* ======================================================
     SAVE ONE ROW
     ------------------------------------------------------
     Atomic writeBatch:
       1. Update ProductStock (location-specific)
       2. Update Products (product-level default) if known
  ====================================================== */

  const saveProduct = async (item, rowKey) => {
    if (!canEditReorder) {
      setError(
        "You do not have permission to edit reorder settings."
      );
      return;
    }

    const productCode = item.ProductCode;

    if (isBlank(productCode)) {
      setError(
        "Product Code is missing from the loaded row."
      );
      return;
    }

    if (isBlank(item.ReOrderLevel) || isBlank(item.ReOrderQty)) {
      setError(
        "Reorder Level and Reorder Qty are required. Enter 0 if none."
      );
      return;
    }

    const reOrderLevel = Number(item.ReOrderLevel);
    const reOrderQtyValue = Number(item.ReOrderQty);

    if (
      !Number.isFinite(reOrderLevel) ||
      !Number.isFinite(reOrderQtyValue)
    ) {
      setError(
        `Invalid reorder value for ${
          item.ProductName || item.ProductCode
        }.`
      );
      return;
    }

    if (reOrderLevel < 0 || reOrderQtyValue < 0) {
      setError("Reorder values cannot be negative.");
      return;
    }

    if (!item._stockDocId) {
      setError(
        "Cannot save: product stock document ID is missing. Refresh and try again."
      );
      return;
    }

    try {
      setSavingId(rowKey);
      setMessage("");
      setError("");

      const batch = writeBatch(db);

      /* ---- 1. ProductStock ---- */

      batch.update(
        doc(db, PRODUCT_STOCK, String(item._stockDocId)),
        {
          ReOrderLevel: reOrderLevel,
          ReOrderQty: reOrderQtyValue,
          UpdatedAt: serverTimestamp(),
          UpdatedBy: username,
        }
      );

      /* ---- 2. Products (product-level default) ---- */

      if (item._productDocId) {
        batch.update(
          doc(db, PRODUCTS, String(item._productDocId)),
          {
            ReOrderLevel: reOrderLevel,
            ReOrderQty: reOrderQtyValue,
            UpdatedAt: serverTimestamp(),
            UpdatedBy: username,
          }
        );
      }

      await batch.commit();

      const label = item.ProductName || item.ProductCode;
      setMessage(`${label} saved successfully.`);

      setProducts((current) =>
        current.map((row) =>
          rowKeyOf(row) === rowKey
            ? {
                ...row,
                ReOrderLevel: reOrderLevel,
                ReOrderQty: reOrderQtyValue,
              }
            : row
        )
      );
    } catch (err) {
      console.error("SAVE REORDER ERROR:", err);
      setError(
        err.message || "Unable to save reorder settings."
      );
    } finally {
      setSavingId(null);
    }
  };

  /* ======================================================
     LOADING GUARD
  ====================================================== */

  if (permsLoading || loading) {
    return (
      <div className="min-h-screen bg-slate-100 p-4 md:p-6">
        <div className="mx-auto max-w-7xl">
          <div className="rounded-xl border border-slate-200 bg-white p-6 shadow-sm">
            <div className="text-sm text-slate-500">
              Loading reorder settings...
            </div>
          </div>
        </div>
      </div>
    );
  }

  if (!canViewReorder) {
    return (
      <div className="min-h-screen bg-slate-100 p-4 md:p-6">
        <div className="mx-auto max-w-7xl">
          <div className="rounded-xl border border-red-200 bg-red-50 p-6 shadow-sm">
            <h1 className="text-lg font-bold text-red-800">
              Access denied
            </h1>
            <p className="mt-1 text-sm text-red-700">
              You do not have permission to view reorder settings.
            </p>
          </div>
        </div>
      </div>
    );
  }

  /* ======================================================
     RENDER
  ====================================================== */

  const inputClass =
    "w-28 rounded-lg border bg-white px-3 py-2 text-right text-sm outline-none focus:ring-2 disabled:cursor-not-allowed disabled:bg-slate-100 disabled:text-slate-500";
  const levelInputClass = `${inputClass} border-blue-300 focus:border-blue-500 focus:ring-blue-100`;
  const qtyInputClass = `${inputClass} border-emerald-300 focus:border-emerald-500 focus:ring-emerald-100`;

  return (
    <div className="min-h-screen bg-slate-100 p-4 md:p-6">
      <div className="mx-auto max-w-7xl">
        {/* HEADER */}
        <div className="mb-5 rounded-xl border border-slate-200 bg-white shadow-sm print:hidden">
          <div className="flex flex-col gap-4 p-5 lg:flex-row lg:items-center lg:justify-between">
            <div>
              <h1 className="text-2xl font-bold text-slate-800">
                Reorder Level &amp; Quantity
              </h1>
              <p className="mt-1 text-sm text-slate-500">
                One value per row — saving updates both
                ProductStock and Products.
              </p>
            </div>

            <div className="flex flex-wrap gap-2">
              {canPrintReorder && (
                <button
                  type="button"
                  onClick={() => window.print()}
                  className="rounded-lg bg-slate-800 px-4 py-2.5 text-sm font-semibold text-white shadow-sm transition hover:bg-slate-700"
                >
                  Print
                </button>
              )}
              <button
                type="button"
                onClick={loadProducts}
                className="rounded-lg bg-blue-600 px-4 py-2.5 text-sm font-semibold text-white shadow-sm transition hover:bg-blue-700"
              >
                Refresh
              </button>
            </div>
          </div>
        </div>

        {/* MESSAGES */}
        {message && (
          <div className="mb-4 rounded-lg border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm font-medium text-emerald-700 print:hidden">
            {message}
          </div>
        )}

        {error && (
          <div className="mb-4 rounded-lg border border-red-200 bg-red-50 px-4 py-3 text-sm font-medium text-red-700 print:hidden">
            {error}
          </div>
        )}

        {/* SEARCH */}
        <div className="mb-5 rounded-xl border border-slate-200 bg-white p-5 shadow-sm print:hidden">
          <div className="flex flex-col gap-3 md:flex-row md:items-end">
            <div className="flex-1">
              <label
                htmlFor="reorder-search"
                className="mb-1 block text-sm font-semibold text-slate-700"
              >
                Search Product
              </label>
              <input
                id="reorder-search"
                type="text"
                value={search}
                onChange={(event) => setSearch(event.target.value)}
                placeholder="Search by product code, product name or location..."
                className="w-full rounded-lg border border-slate-300 bg-white px-4 py-3 text-sm outline-none transition focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
              />
            </div>
            <button
              type="button"
              onClick={() => setSearch("")}
              className="rounded-lg bg-slate-600 px-5 py-3 text-sm font-semibold text-white shadow-sm transition hover:bg-slate-700"
            >
              Clear
            </button>
          </div>

          <div className="mt-3 text-xs text-slate-500">
            Showing{" "}
            <strong className="text-slate-700">
              {filteredProducts.length}
            </strong>{" "}
            of{" "}
            <strong className="text-slate-700">
              {products.length}
            </strong>{" "}
            products
          </div>
        </div>

        {!canEditReorder && (
          <div className="mb-4 rounded-lg border border-amber-200 bg-amber-50 px-4 py-3 text-sm font-medium text-amber-700 print:hidden">
            Read-only access — you can view reorder settings but not
            change them.
          </div>
        )}

        {/* TABLE */}
        <div className="overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm print:rounded-none print:border-0 print:shadow-none">
          <div className="overflow-x-auto">
            <table className="w-full min-w-[900px] border-collapse">
              <thead>
                <tr className="bg-slate-800 text-left text-xs font-semibold uppercase tracking-wider text-white print:bg-white print:text-black">
                  <th className="whitespace-nowrap border border-slate-700 px-4 py-3 print:border-slate-400">
                    Product Code
                  </th>
                  <th className="whitespace-nowrap border border-slate-700 px-4 py-3 print:border-slate-400">
                    Product Name
                  </th>
                  <th className="whitespace-nowrap border border-slate-700 px-4 py-3 print:border-slate-400">
                    Location
                  </th>
                  <th className="whitespace-nowrap border border-slate-700 px-4 py-3 text-right print:border-slate-400">
                    Current Stock
                  </th>
                  <th className="whitespace-nowrap border border-slate-700 px-4 py-3 text-center print:border-slate-400">
                    Reorder Level
                  </th>
                  <th className="whitespace-nowrap border border-slate-700 px-4 py-3 text-center print:border-slate-400">
                    Reorder Qty
                  </th>
                  <th className="whitespace-nowrap border border-slate-700 px-4 py-3 text-center print:hidden">
                    Action
                  </th>
                </tr>
              </thead>

              <tbody className="divide-y divide-slate-200">
                {filteredProducts.length === 0 ? (
                  <tr>
                    <td
                      colSpan="7"
                      className="px-4 py-12 text-center text-sm text-slate-500"
                    >
                      No products found.
                    </td>
                  </tr>
                ) : (
                  filteredProducts.map((item) => {
                    const rowKey = rowKeyOf(item);
                    const isSaving = savingId === rowKey;
                    const readonly = !canEditReorder;
                    const rowLabel =
                      item.ProductName ||
                      item.ProductCode ||
                      "item";

                    return (
                      <tr
                        key={rowKey}
                        className="transition hover:bg-slate-50"
                      >
                        <td className="whitespace-nowrap px-4 py-3 text-sm font-semibold text-slate-800">
                          {item.ProductCode || "-"}
                        </td>
                        <td className="min-w-[220px] px-4 py-3 text-sm text-slate-700">
                          {item.ProductName || "-"}
                        </td>
                        <td className="whitespace-nowrap px-4 py-3 text-sm text-slate-700">
                          {item.LocationName ||
                            item.LocationID ||
                            "-"}
                        </td>
                        <td className="whitespace-nowrap px-4 py-3 text-right text-sm font-semibold text-slate-800">
                          {formatNumber(item.Stock)}
                        </td>

                        <td className="bg-blue-50/60 px-4 py-3 text-center print:bg-white">
                          <input
                            type="number"
                            min="0"
                            step="0.01"
                            disabled={readonly}
                            value={item.ReOrderLevel ?? 0}
                            aria-label={`Reorder level for ${rowLabel}`}
                            onChange={(event) =>
                              handleFieldChange(
                                rowKey,
                                "ReOrderLevel",
                                event.target.value
                              )
                            }
                            className={`${levelInputClass} print:border-0`}
                          />
                        </td>

                        <td className="bg-emerald-50/60 px-4 py-3 text-center print:bg-white">
                          <input
                            type="number"
                            min="0"
                            step="0.01"
                            disabled={readonly}
                            value={item.ReOrderQty ?? 0}
                            aria-label={`Reorder quantity for ${rowLabel}`}
                            onChange={(event) =>
                              handleFieldChange(
                                rowKey,
                                "ReOrderQty",
                                event.target.value
                              )
                            }
                            className={`${qtyInputClass} print:border-0`}
                          />
                        </td>

                        <td className="px-4 py-3 text-center print:hidden">
                          {canEditReorder ? (
                            <button
                              type="button"
                              disabled={isSaving}
                              onClick={() =>
                                saveProduct(item, rowKey)
                              }
                              className={`rounded-lg px-4 py-2 text-xs font-bold text-white shadow-sm transition ${
                                isSaving
                                  ? "cursor-not-allowed bg-slate-400"
                                  : "bg-blue-600 hover:bg-blue-700"
                              }`}
                            >
                              {isSaving ? "Saving..." : "Save"}
                            </button>
                          ) : (
                            <span className="text-xs font-semibold text-slate-400">
                              Read only
                            </span>
                          )}
                        </td>
                      </tr>
                    );
                  })
                )}
              </tbody>
            </table>
          </div>

          <div className="border-t border-slate-200 bg-slate-50 px-4 py-3 text-xs text-slate-500 print:hidden">
            {filteredProducts.length} of {products.length} products
            shown
          </div>
        </div>
      </div>
    </div>
  );
}

export default Reorder;