// src/context/PermissionsContext.jsx
import React, {
  createContext, useContext, useEffect, useMemo, useState, useCallback,
} from "react";
import { doc, getDoc } from "firebase/firestore";
import { db, auth } from "../firebase";

export const PermissionsContext = createContext(null);

const norm = (s) => String(s ?? "").trim().toLowerCase();

const isGranted = (v) => {
  if (v === true)  return true;
  if (v === false || v == null) return false;
  if (typeof v === "number")  return v !== 0;
  if (typeof v === "string") {
    const t = v.trim().toLowerCase();
    return t !== "" && t !== "0" && t !== "false" && t !== "no";
  }
  return Boolean(v);
};

// Reads permissions from users/{uid}.permissions (array of
// { ModuleName, PermissionName, CanView, CanAdd, ... }).
// Can also accept an array of permission rows passed in as `permissionsOverride`.
export function PermissionsProvider({ cashierID, permissionsOverride, children }) {
  const [permissions, setPermissions] = useState(permissionsOverride || []);
  const [loading, setLoading]         = useState(false);
  const [error, setError]             = useState("");

  const load = useCallback(async () => {
    if (permissionsOverride) { setPermissions(permissionsOverride); return; }
    const u = auth.currentUser;
    if (!u) { setPermissions([]); return; }

    setLoading(true); setError("");
    try {
      const snap = await getDoc(doc(db, "users", u.uid));
      const data = snap.exists() ? snap.data() : null;
      setPermissions(Array.isArray(data?.permissions) ? data.permissions : []);
    } catch (e) {
      console.error("[Permissions] load failed:", e);
      setError(e?.message || "Unable to load permissions");
      setPermissions([]);
    } finally {
      setLoading(false);
    }
  }, [permissionsOverride]);

  useEffect(() => { load(); }, [load, cashierID]);

  const index = useMemo(() => {
    const map = new Map();
    for (const p of permissions) {
      const key = norm(p?.ModuleName);
      if (!key) continue;
      let entry = map.get(key);
      if (!entry) { entry = { row: p, byName: new Map() }; map.set(key, entry); }
      const pname = norm(p?.PermissionName);
      if (pname && !entry.byName.has(pname)) entry.byName.set(pname, p);
    }
    return map;
  }, [permissions]);

  const can = useCallback((moduleName, permissionName, action = "CanView") => {
    if (!permissions.length) return false;
    const entry = index.get(norm(moduleName));
    if (!entry) return false;
    const row = permissionName
      ? entry.byName.get(norm(permissionName)) ?? entry.row
      : entry.row;
    return isGranted(row?.[action]);
  }, [index, permissions.length]);

  const canAny = useCallback((moduleName, action = "CanView") => {
    const entry = index.get(norm(moduleName));
    return entry ? isGranted(entry.row?.[action]) : false;
  }, [index]);

  return (
    <PermissionsContext.Provider
      value={{ permissions, loading, error, reload: load, can, canAny }}
    >
      {children}
    </PermissionsContext.Provider>
  );
}

export function usePermissionsContext() {
  const ctx = useContext(PermissionsContext);
  if (!ctx) throw new Error("usePermissionsContext must be inside <PermissionsProvider>");
  return ctx;
}