// src/pos/supplier.js
// ============================================================
// Supplier Master — React + Firestore
// ------------------------------------------------------------
// Preserves:
//   • Full permission gating (View / Add / Edit / Delete)
//   • Field-level permission masking on CreditLimit / CreditPeriod
//   • Cash ↔ Credit payment-method conditional fields
//   • Cheque details, currency
//   • Auto-generated supplier code (S0001, S0002, …)
//   • Soft delete + search
// ============================================================
import React, { useContext, useEffect, useMemo, useState } from "react";
import { AuthContext } from "./SERVER/AuthContext.js";
import { usePermissions } from "../hooks/usePermissions.jsx";
import {
  listCollection,
  createDoc,
  updateDocById,
  softDeleteDoc,
  nextSupplierCode,
} from "../lib/firestore";

const emptyForm = {
  code: "",
  suppliername: "",
  Gender: "",
  address: "",
  mobileno: "",
  email: "",
  contactperson: "",
  paymentMethod: "",
  creditlimit: "",
  CreditPeriod: "",
  chequelimit: "",
  ChequePeriod: "",
  Currancytype: "",
};

// Map currency code ↔ CurrencyID (matching the SQL version)
const currencyToId = (c) =>
  c === "LKR" ? 1 : c === "USD" ? 2 : 0;
const idToCurrency = (id) =>
  Number(id) === 1 ? "LKR" : Number(id) === 2 ? "USD" : "";

export default function Supplier() {
  const { user } = useContext(AuthContext);
  const { can, canField, loading: permissionsLoading } = usePermissions();

  // ---- PERMISSIONS ----
  const canViewSupplier    = can("Supplier", "View");
  const canAddSupplier     = can("Supplier", "Add");
  const canEditSupplier    = can("Supplier", "Edit");
  const canDeleteSupplier  = can("Supplier", "Delete");
  const canViewCreditLimit = canField("Supplier", "CreditLimit");

  // ---- STATE ----
  const [form, setForm]           = useState(emptyForm);
  const [suppliers, setSuppliers] = useState([]);
  const [search, setSearch]       = useState("");
  const [editingId, setEditingId] = useState(null); // Firestore doc id

  const [loading,     setLoading]     = useState(false);
  const [loadingCode, setLoadingCode] = useState(false);

  const [message, setMessage] = useState("");
  const [error,   setError]   = useState("");

  // ============================================================
  // LOAD SUPPLIERS
  // ============================================================
  const loadSuppliers = async () => {
    try {
      setLoading(true);
      setError("");

      const rows = await listCollection("Supplier", {
        where: [["IsDelete", "==", 0]],
      });
      rows.sort((a, b) =>
        String(a.SupplierCode || "").localeCompare(String(b.SupplierCode || ""))
      );
      setSuppliers(rows);
    } catch (err) {
      console.error("LOAD SUPPLIERS ERROR:", err);
      setError(err?.message || "Unable to load suppliers.");
      setSuppliers([]);
    } finally {
      setLoading(false);
    }
  };

  // ============================================================
  // INITIAL LOAD
  // ============================================================
  useEffect(() => {
    if (permissionsLoading) return;
    if (!canViewSupplier) return;
    loadSuppliers();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [permissionsLoading, canViewSupplier]);

  // ============================================================
  // INPUT
  // ============================================================
  const handleChange = (e) => {
    const { name, value } = e.target;

    setForm((prev) => {
      const updated = { ...prev, [name]: value };

      // Payment method drives credit fields
      if (name === "paymentMethod" && value === "Cash") {
        updated.creditlimit  = "0";
        updated.CreditPeriod = "0";
      }
      if (name === "paymentMethod" && value === "Credit") {
        updated.creditlimit  = "";
        updated.CreditPeriod = "";
      }

      return updated;
    });

    setMessage("");
    setError("");
  };

  // ============================================================
  // GENERATE NEXT SUPPLIER CODE
  // ============================================================
  const handleNewSupplier = async () => {
    if (!canAddSupplier) {
      setError("You do not have permission to create suppliers.");
      return;
    }
    try {
      setLoadingCode(true);
      setMessage("");
      setError("");

      const nextCode = await nextSupplierCode();

      setForm({ ...emptyForm, code: nextCode });
      setEditingId(null);
      setMessage(`New supplier code generated: ${nextCode}`);
    } catch (err) {
      console.error("NEW SUPPLIER ERROR:", err);
      setError(err?.message || "Unable to generate supplier code.");
    } finally {
      setLoadingCode(false);
    }
  };

  // ============================================================
  // VALIDATION
  // ============================================================
  const validateForm = () => {
    const code    = String(form.code          ?? "").trim();
    const name    = String(form.suppliername  ?? "").trim();
    const gender  = String(form.Gender        ?? "").trim();
    const address = String(form.address       ?? "").trim();
    const mobile  = String(form.mobileno      ?? "").trim();
    const email   = String(form.email         ?? "").trim();
    const contact = String(form.contactperson ?? "").trim();
    const payment = String(form.paymentMethod ?? "").trim();

    if (!code)    { setError("Supplier code is required.");     return false; }
    if (!name)    { setError("Supplier name is required.");     return false; }
    if (!gender)  { setError("Please select gender.");          return false; }
    if (!address) { setError("Address is required.");           return false; }
    if (!mobile)  { setError("Mobile number is required.");     return false; }
    if (!email)   { setError("Email is required.");             return false; }
    if (!contact) { setError("Contact person is required.");    return false; }
    if (!payment) { setError("Please select payment method.");  return false; }

    if (payment === "Credit" && canViewCreditLimit) {
      if (form.creditlimit  === "") { setError("Credit limit is required.");  return false; }
      if (form.CreditPeriod === "") { setError("Credit period is required."); return false; }
    }
    if (form.chequelimit  === "") { setError("Cheque limit is required.");  return false; }
    if (!form.ChequePeriod)       { setError("Cheque period is required."); return false; }
    if (!form.Currancytype)       { setError("Please select currency.");    return false; }

    return true;
  };

  // ============================================================
  // SAVE / UPDATE
  // ============================================================
  const handleSubmit = async (e) => {
    e.preventDefault();
    setMessage("");
    setError("");

    if (editingId && !canEditSupplier) {
      setError("You do not have permission to edit suppliers.");
      return;
    }
    if (!editingId && !canAddSupplier) {
      setError("You do not have permission to create suppliers.");
      return;
    }

    if (!validateForm()) return;

    try {
      setLoading(true);

      const isCash = form.paymentMethod === "Cash";

      // Build the payload — note that credit fields are only
      // included when the user is allowed to see them. Otherwise
      // the existing server-side values would be overwritten.
      const payload = {
        SupplierCode:      form.code.trim(),
        SupplierName:      form.suppliername.trim(),
        Gender:            form.Gender.trim(),
        BillingAddress1:   form.address.trim(),
        BillingMobile:     form.mobileno.trim(),
        Email:             form.email.trim(),
        ContactPersonName: form.contactperson.trim(),
        PaymentMethod:     form.paymentMethod.trim(),

        ...(canViewCreditLimit && {
          CreditLimit:  isCash ? 0 : Number(form.creditlimit  || 0),
          CreditPeriod: isCash ? 0 : Number(form.CreditPeriod || 0),
        }),

        ChequeLimit:  Number(form.chequelimit  || 0),
        ChequePeriod: Number(form.ChequePeriod || 0),
        CurrencyID:   currencyToId(form.Currancytype),

        IsDelete: 0,
        IsActive: 1,
      };

      if (editingId) {
        await updateDocById("Supplier", editingId, payload, {
          username: user?.username,
        });
        setMessage("Supplier updated successfully.");
      } else {
        // Duplicate code check (only on create)
        const existing = await listCollection("Supplier", {
          where: [
            ["IsDelete", "==", 0],
            ["SupplierCode", "==", form.code.trim()],
          ],
          limit: 1,
        });
        if (existing.length > 0) {
          setError(`Supplier code "${form.code.trim()}" already exists.`);
          return;
        }

        await createDoc("Supplier", payload, {
          customId: form.code.trim(),
          username: user?.username,
        });
        setMessage("Supplier saved successfully.");
      }

      setForm(emptyForm);
      setEditingId(null);
      await loadSuppliers();
    } catch (err) {
      console.error("SAVE SUPPLIER ERROR:", err);
      setError(err?.message || "Failed to save supplier.");
    } finally {
      setLoading(false);
    }
  };

  // ============================================================
  // EDIT
  // ============================================================
  const handleEdit = (s) => {
    if (!canEditSupplier) {
      setError("You do not have permission to edit suppliers.");
      return;
    }

    setForm({
      code:          s.SupplierCode      || "",
      suppliername:  s.SupplierName      || "",
      Gender:        s.Gender            || "",
      address:       s.BillingAddress1   || "",
      mobileno:      s.BillingMobile     || "",
      email:         s.Email             || "",
      contactperson: s.ContactPersonName || "",
      paymentMethod: s.PaymentMethod     || "",
      creditlimit:   s.CreditLimit  ?? "",
      CreditPeriod:  s.CreditPeriod ?? "",
      chequelimit:   s.ChequeLimit  ?? "",
      ChequePeriod:  s.ChequePeriod ?? "",
      Currancytype:  idToCurrency(s.CurrencyID),
    });
    setEditingId(s.id);
    setMessage(`Editing ${s.SupplierCode}`);
    setError("");
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  // ============================================================
  // DELETE (soft)
  // ============================================================
  const handleDelete = async (s) => {
    if (!canDeleteSupplier) {
      setError("You do not have permission to delete suppliers.");
      return;
    }
    if (!s?.id) {
      setError("Invalid supplier.");
      return;
    }
    const confirmed = window.confirm(
      `Are you sure you want to delete "${s.SupplierName || s.SupplierCode}"?`
    );
    if (!confirmed) return;

    try {
      setLoading(true);
      setMessage("");
      setError("");

      await softDeleteDoc("Supplier", s.id, { username: user?.username });
      setMessage("Supplier deleted successfully.");

      if (editingId === s.id) {
        setForm(emptyForm);
        setEditingId(null);
      }
      await loadSuppliers();
    } catch (err) {
      console.error("DELETE SUPPLIER ERROR:", err);
      setError(err?.message || "Failed to delete supplier.");
    } finally {
      setLoading(false);
    }
  };

  // ============================================================
  // CANCEL EDIT
  // ============================================================
  const handleCancel = () => {
    setForm(emptyForm);
    setEditingId(null);
    setMessage("");
    setError("");
  };

  // ============================================================
  // SEARCH
  // ============================================================
  const searchText = search.trim().toLowerCase();
  const filteredSuppliers = useMemo(() => {
    if (!searchText) return suppliers;
    return suppliers.filter((s) => {
      const code    = String(s.SupplierCode      ?? "").toLowerCase();
      const name    = String(s.SupplierName      ?? "").toLowerCase();
      const contact = String(s.ContactPersonName ?? "").toLowerCase();
      const mobile  = String(s.BillingMobile     ?? "").toLowerCase();
      const email   = String(s.Email             ?? "").toLowerCase();
      return (
        code.includes(searchText)    ||
        name.includes(searchText)    ||
        contact.includes(searchText) ||
        mobile.includes(searchText)  ||
        email.includes(searchText)
      );
    });
  }, [suppliers, searchText]);

  // ============================================================
  // COMPUTED
  // ============================================================
  const isEditing    = Boolean(editingId);
  const saveAllowed  = (isEditing && canEditSupplier) || (!isEditing && canAddSupplier);
  const readOnlyEdit = isEditing && !canEditSupplier;

  // ============================================================
  // ACCESS GATE
  // ============================================================
  if (permissionsLoading) {
    return (
      <div className="min-h-screen bg-gray-100 p-6 flex items-center justify-center text-gray-500">
        Checking permissions…
      </div>
    );
  }

  if (!canViewSupplier) {
    return (
      <div className="min-h-screen bg-gray-100 p-6">
        <div className="mx-auto max-w-xl mt-20 rounded-xl border border-red-200 bg-red-50 p-8 text-center">
          <h2 className="text-lg font-bold text-red-700">Access Denied</h2>
          <p className="text-sm text-red-600 mt-2">
            You do not have permission to view Supplier Master.
          </p>
          <p className="text-xs text-red-400 mt-3">
            Module: <code>Supplier</code>
          </p>
        </div>
      </div>
    );
  }

  // ============================================================
  // RENDER
  // ============================================================
  return (
    <div className="min-h-screen bg-gray-100 p-4 md:p-6">

      {/* HEADER */}
      <div className="mb-6 flex flex-col gap-3 md:flex-row md:items-center md:justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-800">Supplier Master</h1>
          <p className="text-sm text-gray-500">Create, edit and manage suppliers</p>
        </div>

        <div className="flex items-center gap-3">
          {readOnlyEdit && (
            <span className="rounded-full bg-slate-200 px-3 py-1 text-xs font-semibold text-slate-600">
              READ ONLY
            </span>
          )}
          <div className="rounded-lg bg-gray-50 border border-gray-200 px-4 py-2 text-sm text-gray-700">
            <span className="text-xs text-gray-500">User: </span>
            <span className="font-semibold">{user?.username || "—"}</span>
          </div>
          {canAddSupplier && (
            <button
              type="button"
              onClick={handleNewSupplier}
              disabled={loadingCode}
              className="rounded-lg bg-blue-600 px-5 py-2.5 font-semibold text-white shadow hover:bg-blue-700 disabled:opacity-50"
            >
              {loadingCode ? "Generating…" : "+ New Supplier"}
            </button>
          )}
        </div>
      </div>

      {/* MESSAGES */}
      {message && (
        <div className="mb-4 rounded-lg border border-green-200 bg-green-50 px-4 py-3 text-sm font-medium text-green-700">
          ✓ {message}
        </div>
      )}
      {error && (
        <div className="mb-4 rounded-lg border border-red-200 bg-red-50 px-4 py-3 text-sm font-medium text-red-700">
          ⚠ {error}
        </div>
      )}

      {/* FORM */}
      <form onSubmit={handleSubmit} className="rounded-xl bg-white p-5 shadow-md">
        <div className="mb-5 flex items-center justify-between border-b pb-3">
          <h2 className="text-lg font-bold text-gray-800">
            {isEditing ? "Edit Supplier" : "Supplier Details"}
          </h2>
          {isEditing && (
            <span className="rounded-full bg-yellow-100 px-3 py-1 text-xs font-semibold text-yellow-800">
              EDIT MODE
            </span>
          )}
        </div>

        {/* ROW 1 — Code / Name / Gender */}
        <div className="grid grid-cols-1 gap-4 md:grid-cols-3">
          <div>
            <label className="mb-1 block text-sm font-semibold text-gray-700">
              Supplier Code <span className="text-red-500">*</span>
            </label>
            <div className="flex gap-2">
              <input
                type="text"
                name="code"
                value={form.code}
                onChange={handleChange}
                readOnly={isEditing}
                className={`w-full rounded-lg border px-3 py-2 outline-none ${
                  isEditing ? "bg-gray-100" : "focus:border-blue-500"
                }`}
              />
              {!isEditing && canAddSupplier && (
                <button
                  type="button"
                  onClick={handleNewSupplier}
                  disabled={loadingCode}
                  className="rounded-lg bg-gray-700 px-4 text-white hover:bg-gray-800 disabled:opacity-50"
                >
                  {loadingCode ? "…" : "New"}
                </button>
              )}
            </div>
          </div>

          <div>
            <label className="mb-1 block text-sm font-semibold text-gray-700">
              Supplier Name <span className="text-red-500">*</span>
            </label>
            <input
              type="text"
              name="suppliername"
              value={form.suppliername}
              onChange={handleChange}
              className="w-full rounded-lg border px-3 py-2 outline-none focus:border-blue-500"
            />
          </div>

          <div>
            <label className="mb-1 block text-sm font-semibold text-gray-700">
              Gender
            </label>
            <select
              name="Gender"
              value={form.Gender}
              onChange={handleChange}
              className="w-full rounded-lg border px-3 py-2 outline-none focus:border-blue-500"
            >
              <option value="">Select Gender</option>
              <option value="Male">Male</option>
              <option value="Female">Female</option>
              <option value="Company">Company</option>
            </select>
          </div>
        </div>

        {/* ROW 2 — Address / Mobile / Email */}
        <div className="mt-4 grid grid-cols-1 gap-4 md:grid-cols-2">
          <div>
            <label className="mb-1 block text-sm font-semibold text-gray-700">
              Address <span className="text-red-500">*</span>
            </label>
            <textarea
              name="address"
              value={form.address}
              onChange={handleChange}
              rows={3}
              className="w-full rounded-lg border px-3 py-2 outline-none focus:border-blue-500"
            />
          </div>

          <div className="grid grid-cols-1 gap-4">
            <div>
              <label className="mb-1 block text-sm font-semibold text-gray-700">
                Mobile <span className="text-red-500">*</span>
              </label>
              <input
                type="text"
                name="mobileno"
                value={form.mobileno}
                onChange={handleChange}
                className="w-full rounded-lg border px-3 py-2 outline-none focus:border-blue-500"
              />
            </div>
            <div>
              <label className="mb-1 block text-sm font-semibold text-gray-700">
                Email <span className="text-red-500">*</span>
              </label>
              <input
                type="email"
                name="email"
                value={form.email}
                onChange={handleChange}
                className="w-full rounded-lg border px-3 py-2 outline-none focus:border-blue-500"
              />
            </div>
          </div>
        </div>

        {/* ROW 3 — Contact / Payment / Currency */}
        <div className="mt-4 grid grid-cols-1 gap-4 md:grid-cols-3">
          <div>
            <label className="mb-1 block text-sm font-semibold text-gray-700">
              Contact Person <span className="text-red-500">*</span>
            </label>
            <input
              type="text"
              name="contactperson"
              value={form.contactperson}
              onChange={handleChange}
              className="w-full rounded-lg border px-3 py-2 outline-none focus:border-blue-500"
            />
          </div>

          <div>
            <label className="mb-1 block text-sm font-semibold text-gray-700">
              Payment Method <span className="text-red-500">*</span>
            </label>
            <select
              name="paymentMethod"
              value={form.paymentMethod}
              onChange={handleChange}
              className="w-full rounded-lg border px-3 py-2 outline-none focus:border-blue-500"
            >
              <option value="">Select Payment</option>
              <option value="Cash">Cash</option>
              <option value="Credit">Credit</option>
            </select>
          </div>

          <div>
            <label className="mb-1 block text-sm font-semibold text-gray-700">
              Currency <span className="text-red-500">*</span>
            </label>
            <select
              name="Currancytype"
              value={form.Currancytype}
              onChange={handleChange}
              className="w-full rounded-lg border px-3 py-2 outline-none focus:border-blue-500"
            >
              <option value="">Select Currency</option>
              <option value="LKR">LKR</option>
              <option value="USD">USD</option>
            </select>
          </div>
        </div>

        {/* CREDIT DETAILS — only when paymentMethod = Credit AND user can view credit */}
        {form.paymentMethod === "Credit" && canViewCreditLimit && (
          <div className="mt-5 rounded-lg border border-blue-200 bg-blue-50 p-4">
            <h3 className="mb-3 font-bold text-blue-800">Credit Details</h3>
            <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
              <div>
                <label className="mb-1 block text-sm font-semibold">
                  Credit Limit <span className="text-red-500">*</span>
                </label>
                <input
                  type="number"
                  min="0"
                  name="creditlimit"
                  value={form.creditlimit}
                  onChange={handleChange}
                  className="w-full rounded-lg border px-3 py-2"
                />
              </div>
              <div>
                <label className="mb-1 block text-sm font-semibold">
                  Credit Period <span className="text-red-500">*</span>
                </label>
                <select
                  name="CreditPeriod"
                  value={form.CreditPeriod}
                  onChange={handleChange}
                  className="w-full rounded-lg border px-3 py-2"
                >
                  <option value="">Select Period</option>
                  <option value="45">45 Days</option>
                  <option value="90">90 Days</option>
                </select>
              </div>
            </div>
          </div>
        )}

        {/* Notice when credit fields are hidden by permission */}
        {form.paymentMethod === "Credit" && !canViewCreditLimit && (
          <div className="mt-5 rounded-lg border border-amber-200 bg-amber-50 px-4 py-3 text-xs font-medium text-amber-700">
            Credit Limit and Credit Period are hidden by your permission level.
            Existing values will be preserved on save.
          </div>
        )}

        {/* CHEQUE DETAILS */}
        <div className="mt-5 rounded-lg border border-gray-200 bg-gray-50 p-4">
          <h3 className="mb-3 font-bold text-gray-800">Cheque Details</h3>
          <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
            <div>
              <label className="mb-1 block text-sm font-semibold">
                Cheque Limit <span className="text-red-500">*</span>
              </label>
              <input
                type="number"
                min="0"
                name="chequelimit"
                value={form.chequelimit}
                onChange={handleChange}
                className="w-full rounded-lg border px-3 py-2"
              />
            </div>
            <div>
              <label className="mb-1 block text-sm font-semibold">
                Cheque Period <span className="text-red-500">*</span>
              </label>
              <select
                name="ChequePeriod"
                value={form.ChequePeriod}
                onChange={handleChange}
                className="w-full rounded-lg border px-3 py-2"
              >
                <option value="">Select Period</option>
                <option value="45">45 Days</option>
                <option value="90">90 Days</option>
              </select>
            </div>
          </div>
        </div>

        {/* BUTTONS */}
        <div className="mt-6 flex flex-wrap items-center gap-3">
          {saveAllowed && (
            <button
              type="submit"
              disabled={loading}
              className={`rounded-lg px-6 py-2.5 font-semibold text-white ${
                isEditing
                  ? "bg-orange-600 hover:bg-orange-700"
                  : "bg-green-600 hover:bg-green-700"
              } disabled:opacity-50`}
            >
              {loading
                ? "Processing…"
                : isEditing
                ? "Update Supplier"
                : "Save Supplier"}
            </button>
          )}

          {isEditing && (
            <button
              type="button"
              onClick={handleCancel}
              className="rounded-lg bg-gray-500 px-6 py-2.5 font-semibold text-white hover:bg-gray-600"
            >
              Cancel
            </button>
          )}

          {readOnlyEdit && (
            <div className="flex items-center rounded-lg border border-slate-200 bg-slate-50 px-4 py-2.5 text-xs font-semibold text-slate-500">
              You have read-only access — editing is disabled.
            </div>
          )}

          {!isEditing && !canAddSupplier && (
            <div className="flex items-center rounded-lg border border-slate-200 bg-slate-50 px-4 py-2.5 text-xs font-semibold text-slate-500">
              You do not have permission to create new suppliers.
            </div>
          )}
        </div>
      </form>

      {/* LIST */}
      <div className="mt-6 rounded-xl bg-white p-5 shadow-md">
        <div className="mb-4 flex flex-col gap-3 md:flex-row md:items-center md:justify-between">
          <h2 className="text-lg font-bold text-gray-800">
            Supplier List{" "}
            <span className="ml-1 text-sm font-normal text-gray-500">
              ({filteredSuppliers.length})
            </span>
          </h2>

          <input
            type="text"
            placeholder="Search code, name, mobile, email…"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="w-full rounded-lg border px-4 py-2 outline-none focus:border-blue-500 md:w-96"
          />
        </div>

        <div className="overflow-x-auto">
          <table className="min-w-full border-collapse">
            <thead>
              <tr className="bg-gray-800 text-left text-sm text-white">
                <th className="px-4 py-3">Code</th>
                <th className="px-4 py-3">Supplier Name</th>
                <th className="px-4 py-3">Contact Person</th>
                <th className="px-4 py-3">Mobile</th>
                <th className="px-4 py-3">Payment</th>
                {canViewCreditLimit && <th className="px-4 py-3">Credit Limit</th>}
                <th className="px-4 py-3">Currency</th>
                <th className="px-4 py-3 text-center">Actions</th>
              </tr>
            </thead>

            <tbody>
              {loading && suppliers.length === 0 ? (
                <tr>
                  <td
                    colSpan={canViewCreditLimit ? 8 : 7}
                    className="px-4 py-8 text-center text-gray-500"
                  >
                    Loading suppliers…
                  </td>
                </tr>
              ) : filteredSuppliers.length === 0 ? (
                <tr>
                  <td
                    colSpan={canViewCreditLimit ? 8 : 7}
                    className="px-4 py-8 text-center text-gray-500"
                  >
                    No suppliers found.
                  </td>
                </tr>
              ) : (
                filteredSuppliers.map((s) => (
                  <tr key={s.id} className="border-b hover:bg-gray-50">
                    <td className="px-4 py-3 font-semibold">{s.SupplierCode}</td>
                    <td className="px-4 py-3">{s.SupplierName}</td>
                    <td className="px-4 py-3">{s.ContactPersonName || "-"}</td>
                    <td className="px-4 py-3">{s.BillingMobile || "-"}</td>
                    <td className="px-4 py-3">{s.PaymentMethod || "-"}</td>

                    {canViewCreditLimit && (
                      <td className="px-4 py-3">
                        {Number(s.CreditLimit || 0).toFixed(2)}
                      </td>
                    )}

                    <td className="px-4 py-3">
                      {idToCurrency(s.CurrencyID) || "-"}
                    </td>

                    <td className="px-4 py-3">
                      <div className="flex justify-center gap-2">
                        {canEditSupplier && (
                          <button
                            type="button"
                            onClick={() => handleEdit(s)}
                            className="rounded-lg bg-blue-600 px-3 py-1.5 text-sm font-semibold text-white hover:bg-blue-700"
                          >
                            Edit
                          </button>
                        )}
                        {canDeleteSupplier && (
                          <button
                            type="button"
                            onClick={() => handleDelete(s)}
                            className="rounded-lg bg-red-600 px-3 py-1.5 text-sm font-semibold text-white hover:bg-red-700"
                          >
                            Delete
                          </button>
                        )}
                        {!canEditSupplier && !canDeleteSupplier && (
                          <span className="text-xs text-slate-400">No actions</span>
                        )}
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

    </div>
  );
}