// src/hooks/usePermissions.jsx
import { useContext } from "react";
import { PermissionsContext } from "../context/PermissionsContext";

const ACTION_TO_COLUMN = {
  View: "CanView", Add: "CanAdd", Edit: "CanEdit",
  Delete: "CanDelete", Print: "CanPrint",
};

const FIELD_TO_COLUMN = {
  CostPrice:       "CanViewCostPrice",
  SellingPrice:    "CanViewSellingPrice",
  Profit:          "CanViewProfit",
  CreditLimit:     "CanViewCreditLimit",
  MinimumDiscount: "CanViewMinimumDiscount",
  MaximumDiscount: "CanViewMaximumDiscount",
  PurchaseLimit:   "CanViewPurchaseLimit",
};

export function usePermissions() {
  const ctx = useContext(PermissionsContext);
  if (!ctx) throw new Error("usePermissions must be inside <PermissionsProvider>");

  const can = (moduleName, action = "View") =>
    ctx.can(moduleName, null, ACTION_TO_COLUMN[action] || action);

  const canField = (moduleName, field) => {
    const column = FIELD_TO_COLUMN[field];
    if (!column) return true;
    return ctx.can(moduleName, null, column);
  };

  return {
    permissions: ctx.permissions,
    loading:     ctx.loading,
    error:       ctx.error,
    reload:      ctx.reload,
    can,
    canField,
  };
}