// AccountTransactionLogs.jsx
import React, { useCallback, useEffect, useMemo, useState } from "react";
import {
  Search,
  Download,
  CalendarDays,
  ChevronDown,
  RefreshCw,
  Filter,
  X,
  ArrowUp,
  ArrowDown,
  Activity,
} from "lucide-react";
import * as XLSX from "xlsx";
import {
  COLLECTIONS,
  listCollection,
} from "../lib/firestore.js";

const AccountTransactionLogs = () => {
  const [transactions, setTransactions] = useState([]);
  const [accounts, setAccounts] = useState([]);

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const [search, setSearch] = useState("");
  const [accountId, setAccountId] = useState("");
  const [type, setType] = useState("");
  const [userName, setUserName] = useState("");
  const [fromDate, setFromDate] = useState("");
  const [toDate, setToDate] = useState("");

  /* ---------- LOAD ACCOUNTS ---------- */
  const loadAccounts = useCallback(async () => {
    try {
      const rows = await listCollection(COLLECTIONS.ACCOUNTS, {
        where: [["IsDelete", "==", 0]],
      });
      setAccounts(
        rows.map((a) => ({
          AccountID: a.id,
          AccountName: a.AccountName || a.name || "Unnamed",
        }))
      );
    } catch (err) {
      console.error("Accounts error:", err);
    }
  }, []);

  /* ---------- LOAD TRANSACTIONS ---------- */
  const loadTransactions = useCallback(async () => {
    try {
      setLoading(true);
      setError("");

      const rows = await listCollection(COLLECTIONS.ACCOUNT_TRANSACTIONS, {
        where: [["IsDelete", "==", 0]],
      });

      // Normalize & sort (client-side; latest first)
      const normalized = rows
        .map((r) => ({
          LedgerID: r.id,
          TransactionDate: r.TransactionDate || r.date || null,
          AccountName: r.AccountName || r.accountName || "-",
          AccountType: r.AccountType || r.accountType || "",
          DetailType: r.DetailType || r.detailType || "",
          TransactionType: r.TransactionType || r.transactionType || "",
          ReferenceNo: r.ReferenceNo || r.referenceNo || "",
          Description: r.Description || r.description || "",
          Debit: Number(r.Debit || r.debit || 0),
          Credit: Number(r.Credit || r.credit || 0),
          CreatedBy: r.CreatedBy || r.createdBy || "-",
          CreatedDate: r.CreatedAt || r.CreatedDate || null,
        }))
        .sort((a, b) => {
          const da = a.TransactionDate ? new Date(a.TransactionDate).getTime() : 0;
          const db = b.TransactionDate ? new Date(b.TransactionDate).getTime() : 0;
          return db - da;
        });

      setTransactions(normalized);
    } catch (err) {
      console.error("Transaction error:", err);
      setTransactions([]);
      setError(err.message || "Unable to load transactions");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadAccounts();
    loadTransactions();
  }, [loadAccounts, loadTransactions]);

  /* ---------- FILTERS (client-side) ---------- */
  const filtered = useMemo(() => {
    const q = search.trim().toLowerCase();

    return transactions.filter((t) => {
      if (accountId && t.AccountName) {
        const acct = accounts.find((a) => a.AccountID === accountId);
        if (!acct || t.AccountName !== acct.AccountName) return false;
      }
      if (type && t.TransactionType !== type) return false;
      if (userName && t.CreatedBy !== userName) return false;

      if (fromDate) {
        const d = new Date(t.TransactionDate || 0).getTime();
        if (Number.isFinite(d) && d < new Date(fromDate).getTime()) return false;
      }
      if (toDate) {
        const d = new Date(t.TransactionDate || 0).getTime();
        const end = new Date(toDate);
        end.setHours(23, 59, 59, 999);
        if (Number.isFinite(d) && d > end.getTime()) return false;
      }

      if (q) {
        const haystack = `${t.Description} ${t.ReferenceNo} ${t.AccountName}`.toLowerCase();
        if (!haystack.includes(q)) return false;
      }
      return true;
    });
  }, [transactions, accounts, search, accountId, type, userName, fromDate, toDate]);

  /* ---------- DISTINCT FILTER OPTIONS ---------- */
  const types = useMemo(
    () => [...new Set(transactions.map((t) => t.TransactionType).filter(Boolean))].sort(),
    [transactions]
  );
  const users = useMemo(
    () => [...new Set(transactions.map((t) => t.CreatedBy).filter(Boolean))].sort(),
    [transactions]
  );

  /* ---------- HELPERS ---------- */
  const clearFilters = () => {
    setSearch("");
    setAccountId("");
    setType("");
    setUserName("");
    setFromDate("");
    setToDate("");
  };

  const formatDateTime = (value) => {
    if (!value) return "-";
    const date = new Date(value);
    if (Number.isNaN(date.getTime())) return "-";
    const pad = (n) => String(n).padStart(2, "0");
    return `${pad(date.getDate())}/${pad(date.getMonth() + 1)}/${date.getFullYear()}, ${pad(
      date.getHours()
    )}:${pad(date.getMinutes())}:${pad(date.getSeconds())}`;
  };

  const formatAmount = (value) =>
    Number(value || 0).toLocaleString("en-US", {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    });

  const totalCredit = useMemo(
    () => filtered.reduce((s, x) => s + Number(x.Credit || 0), 0),
    [filtered]
  );
  const totalDebit = useMemo(
    () => filtered.reduce((s, x) => s + Number(x.Debit || 0), 0),
    [filtered]
  );
  const netAmount = totalCredit - totalDebit;

  const activeFilterCount = useMemo(
    () =>
      [search.trim(), accountId, type, userName, fromDate, toDate].filter(Boolean).length,
    [search, accountId, type, userName, fromDate, toDate]
  );

  const exportToExcel = () => {
    if (!filtered.length) {
      alert("There are no transactions to export.");
      return;
    }
    const data = filtered.map((item) => ({
      "Date & Time": formatDateTime(item.TransactionDate),
      Account: item.AccountName,
      "Account Type": item.AccountType,
      "Detail Type": item.DetailType,
      "Transaction Type": item.TransactionType,
      "Reference No": item.ReferenceNo,
      Description: item.Description,
      Debit: item.Debit,
      Credit: item.Credit,
      "Created By": item.CreatedBy,
      "Created Date": formatDateTime(item.CreatedDate),
    }));
    const ws = XLSX.utils.json_to_sheet(data);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Account Transactions");
    XLSX.writeFile(wb, "Account_Transaction_Logs.xlsx");
  };

  /* ---------- RENDER ---------- */
  return (
    <div className="min-h-screen bg-slate-100 p-3 sm:p-4 lg:p-6">
      <div className="mx-auto max-w-[1800px]">
        {/* HEADER (same structure as original) */}
        <div className="mb-5 overflow-hidden rounded-2xl bg-white shadow-sm ring-1 ring-slate-200">
          <div className="bg-gradient-to-r from-slate-900 via-slate-800 to-blue-900 px-5 py-6 sm:px-6">
            <div className="flex flex-col gap-5 lg:flex-row lg:items-center lg:justify-between">
              <div className="flex items-start gap-4">
                <div className="hidden rounded-xl bg-white/10 p-3 ring-1 ring-white/20 sm:block">
                  <Activity className="h-7 w-7 text-white" />
                </div>
                <div>
                  <h1 className="text-2xl font-bold tracking-tight text-white sm:text-3xl">
                    Account Transaction Logs
                  </h1>
                  <p className="mt-1 text-sm text-slate-300">
                    View all account transactions with user tracking
                  </p>
                </div>
              </div>
              <div className="flex flex-wrap gap-2">
                <button
                  type="button"
                  onClick={loadTransactions}
                  disabled={loading}
                  className="inline-flex items-center justify-center gap-2 rounded-xl border border-white/20 bg-white/10 px-4 py-2.5 text-sm font-semibold text-white backdrop-blur transition hover:bg-white/20 disabled:opacity-50"
                >
                  <RefreshCw size={17} className={loading ? "animate-spin" : ""} />
                  Refresh
                </button>
                <button
                  type="button"
                  onClick={exportToExcel}
                  className="inline-flex items-center justify-center gap-2 rounded-xl bg-white px-4 py-2.5 text-sm font-semibold text-slate-800 shadow-sm hover:bg-slate-100"
                >
                  <Download size={17} />
                  Export to Excel
                </button>
              </div>
            </div>
          </div>

          <div className="grid grid-cols-1 divide-y divide-slate-200 sm:grid-cols-3 sm:divide-x sm:divide-y-0">
            <Stat icon={<Activity className="h-5 w-5 text-slate-600" />} bg="bg-slate-100" label="Transactions" value={filtered.length.toLocaleString()} />
            <Stat icon={<ArrowUp className="h-5 w-5 text-emerald-600" />} bg="bg-emerald-50" label="Total Credit" value={`+${formatAmount(totalCredit)}`} color="text-emerald-600" />
            <Stat icon={<ArrowDown className="h-5 w-5 text-red-600" />} bg="bg-red-50" label="Total Debit" value={`-${formatAmount(totalDebit)}`} color="text-red-600" />
          </div>
        </div>

        {/* FILTERS */}
        <div className="mb-5 rounded-2xl bg-white p-4 shadow-sm ring-1 ring-slate-200 sm:p-5">
          <div className="mb-4 flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
            <div className="flex items-center gap-2">
              <div className="rounded-lg bg-blue-50 p-2">
                <Filter className="h-5 w-5 text-blue-600" />
              </div>
              <div>
                <h2 className="text-lg font-bold text-slate-800">Filters</h2>
                <p className="text-xs text-slate-500">Filter account transaction records</p>
              </div>
            </div>
            {activeFilterCount > 0 && (
              <div className="inline-flex w-fit items-center gap-2 rounded-full bg-blue-50 px-3 py-1.5 text-xs font-semibold text-blue-700">
                <span>{activeFilterCount} active filter{activeFilterCount === 1 ? "" : "s"}</span>
                <button onClick={clearFilters} className="rounded-full p-0.5 hover:bg-blue-100">
                  <X size={14} />
                </button>
              </div>
            )}
          </div>

          <div className="grid grid-cols-1 gap-3 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 2xl:grid-cols-7">
            <div className="relative 2xl:col-span-2">
              <label className="mb-1.5 block text-xs font-semibold text-slate-600">Search</label>
              <Search size={17} className="absolute left-3 top-[35px] -translate-y-1/2 text-slate-400" />
              <input
                type="text"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                placeholder="Description, reference..."
                className="w-full rounded-xl border border-slate-300 bg-white py-2.5 pl-10 pr-3 text-sm outline-none focus:border-blue-500 focus:ring-4 focus:ring-blue-50"
              />
            </div>

            <SelectInput
              label="Account"
              value={accountId}
              onChange={(e) => setAccountId(e.target.value)}
              options={[{ value: "", label: "All Accounts" }, ...accounts.map((a) => ({ value: a.AccountID, label: a.AccountName }))]}
            />

            <SelectInput
              label="Transaction Type"
              value={type}
              onChange={(e) => setType(e.target.value)}
              options={[{ value: "", label: "All Types" }, ...types.map((t) => ({ value: t, label: t }))]}
            />

            <SelectInput
              label="Created By"
              value={userName}
              onChange={(e) => setUserName(e.target.value)}
              options={[{ value: "", label: "All Users" }, ...users.map((u) => ({ value: u, label: u }))]}
            />

            <DateInput label="From Date" value={fromDate} onChange={(e) => setFromDate(e.target.value)} />
            <DateInput label="To Date" value={toDate} min={fromDate || undefined} onChange={(e) => setToDate(e.target.value)} />

            <div className="flex items-end">
              <button
                type="button"
                onClick={clearFilters}
                className="inline-flex w-full items-center justify-center gap-2 rounded-xl border border-slate-300 bg-slate-50 px-4 py-2.5 text-sm font-semibold text-slate-700 hover:bg-slate-100"
              >
                <X size={16} />
                Clear Filters
              </button>
            </div>
          </div>
        </div>

        {error && (
          <div className="mb-5 rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">{error}</div>
        )}

        {/* TABLE */}
        <div className="overflow-hidden rounded-2xl bg-white shadow-sm ring-1 ring-slate-200">
          <div className="border-b border-slate-200 px-4 py-4 sm:px-5">
            <div className="flex flex-col gap-4 lg:flex-row lg:items-center lg:justify-between">
              <div>
                <div className="flex items-center gap-2">
                  <h2 className="text-lg font-bold text-slate-800">Transactions</h2>
                  <span className="rounded-full bg-slate-100 px-2.5 py-1 text-xs font-bold text-slate-600">
                    {filtered.length}
                  </span>
                </div>
                <p className="mt-1 text-xs text-slate-500">Account ledger transaction history</p>
              </div>
              <div className="flex flex-wrap gap-2">
                <Badge label="Credit" value={`+${formatAmount(totalCredit)}`} tone="emerald" />
                <Badge label="Debit" value={`-${formatAmount(totalDebit)}`} tone="red" />
                <Badge label="Net" value={`${netAmount >= 0 ? "+" : "-"}${formatAmount(Math.abs(netAmount))}`} tone={netAmount >= 0 ? "blue" : "amber"} />
              </div>
            </div>
          </div>

          <div className="overflow-x-auto">
            <table className="min-w-[1100px] w-full text-left text-sm">
              <thead className="border-b border-slate-200 bg-slate-50">
                <tr>
                  {["Date & Time", "Account", "Type", "Amount", "Description", "Reference", "User"].map((h) => (
                    <th key={h} className={`whitespace-nowrap px-5 py-3.5 text-xs font-bold uppercase tracking-wide text-slate-500 ${h === "Amount" ? "text-right" : ""}`}>
                      {h}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {loading && <tr><td colSpan={7} className="px-5 py-16 text-center text-slate-500">Loading...</td></tr>}
                {!loading && filtered.length === 0 && (
                  <tr><td colSpan={7} className="px-5 py-16 text-center text-slate-500">No transactions found.</td></tr>
                )}
                {!loading &&
                  filtered.map((item) => {
                    const isCredit = item.Credit > 0;
                    const amount = isCredit ? item.Credit : item.Debit;
                    return (
                      <tr key={item.LedgerID} className="hover:bg-slate-50">
                        <td className="whitespace-nowrap px-5 py-4">
                          <div className="font-medium text-slate-700">{formatDateTime(item.TransactionDate)}</div>
                          {item.CreatedDate && (
                            <div className="mt-1 text-[11px] text-slate-400">Created: {formatDateTime(item.CreatedDate)}</div>
                          )}
                        </td>
                        <td className="px-5 py-4">
                          <div className="font-semibold text-slate-800">{item.AccountName}</div>
                          {item.AccountType && <div className="mt-1 inline-flex rounded-md bg-slate-100 px-2 py-0.5 text-xs text-slate-500">{item.AccountType}</div>}
                        </td>
                        <td className="px-5 py-4">
                          <span className={`inline-flex items-center rounded-full px-2.5 py-1 text-xs font-bold ${isCredit ? "bg-emerald-100 text-emerald-700" : "bg-red-100 text-red-700"}`}>
                            <span className={`mr-1.5 h-1.5 w-1.5 rounded-full ${isCredit ? "bg-emerald-500" : "bg-red-500"}`} />
                            {item.TransactionType || (isCredit ? "CREDIT" : "DEBIT")}
                          </span>
                        </td>
                        <td className={`px-5 py-4 text-right font-bold ${isCredit ? "text-emerald-600" : "text-red-600"}`}>
                          {isCredit ? "+" : "-"}{formatAmount(amount)}
                          <div className="mt-1 text-[10px] uppercase text-slate-400">{isCredit ? "Credit" : "Debit"}</div>
                        </td>
                        <td className="max-w-[350px] px-5 py-4"><div className="truncate text-slate-600" title={item.Description}>{item.Description || "-"}</div></td>
                        <td className="px-5 py-4">{item.ReferenceNo ? <span className="inline-flex rounded-lg bg-slate-100 px-2.5 py-1 font-mono text-xs text-slate-600">{item.ReferenceNo}</span> : <span className="text-slate-400">-</span>}</td>
                        <td className="px-5 py-4 font-medium text-slate-600">{item.CreatedBy}</td>
                      </tr>
                    );
                  })}
              </tbody>
            </table>
          </div>

          {!loading && filtered.length > 0 && (
            <div className="border-t border-slate-200 bg-slate-50 px-5 py-3 text-xs text-slate-500">
              Showing {filtered.length.toLocaleString()} of {transactions.length.toLocaleString()} transactions
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

/* ---------- SMALL UI ATOMS ---------- */
const Stat = ({ icon, bg, label, value, color = "text-slate-800" }) => (
  <div className="flex items-center gap-3 px-5 py-4">
    <div className={`rounded-lg ${bg} p-2`}>{icon}</div>
    <div>
      <p className="text-xs font-medium uppercase tracking-wide text-slate-500">{label}</p>
      <p className={`text-lg font-bold ${color}`}>{value}</p>
    </div>
  </div>
);

const Badge = ({ label, value, tone }) => {
  const tones = {
    emerald: "border-emerald-100 bg-emerald-50 text-emerald-700",
    red: "border-red-100 bg-red-50 text-red-700",
    blue: "border-blue-100 bg-blue-50 text-blue-700",
    amber: "border-amber-100 bg-amber-50 text-amber-700",
  };
  return (
    <div className={`rounded-xl border px-3 py-2 text-sm ${tones[tone]}`}>
      <span>{label}:</span> <strong className="ml-1">{value}</strong>
    </div>
  );
};

const SelectInput = ({ label, value, onChange, options }) => (
  <div>
    <label className="mb-1.5 block text-xs font-semibold text-slate-600">{label}</label>
    <div className="relative">
      <select
        value={value}
        onChange={onChange}
        className="w-full appearance-none rounded-xl border border-slate-300 bg-white px-3 py-2.5 pr-10 text-sm outline-none focus:border-blue-500 focus:ring-4 focus:ring-blue-50"
      >
        {options.map((o) => (
          <option key={o.value} value={o.value}>{o.label}</option>
        ))}
      </select>
      <ChevronDown size={17} className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-slate-400" />
    </div>
  </div>
);

const DateInput = ({ label, value, onChange, min }) => (
  <div>
    <label className="mb-1.5 block text-xs font-semibold text-slate-600">{label}</label>
    <div className="relative">
      <input
        type="date"
        value={value}
        onChange={onChange}
        min={min}
        className="w-full rounded-xl border border-slate-300 bg-white px-3 py-2.5 text-sm outline-none focus:border-blue-500 focus:ring-4 focus:ring-blue-50"
      />
      <CalendarDays size={16} className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-slate-400" />
    </div>
  </div>
);

export default AccountTransactionLogs;